//! Clone-heavy code that needs refactoring.

#[derive(Debug, Clone, PartialEq)]
pub struct Config {
    pub name: String,
    pub value: i32,
    pub tags: Vec<String>,
}

impl Config {
    pub fn new(name: String, value: i32, tags: Vec<String>) -> Self {
        Config { name, value, tags }
    }

    /// Returns config name. CLONE-HEAVY: clones unnecessarily.
    pub fn get_name(&self) -> String {
        self.name.clone() // should return &str
    }

    /// Returns tags. CLONE-HEAVY: clones all tags.
    pub fn get_tags(&self) -> Vec<String> {
        self.tags.clone() // should return &[String]
    }

    /// Returns formatted string. CLONE-HEAVY: clones name just to format.
    pub fn summary(&self) -> String {
        format!("{}={} tags={:?}", self.name.clone(), self.value, self.tags.clone())
    }

    /// Check if tag exists. CLONE-HEAVY: clones each tag for comparison.
    pub fn has_tag(&self, tag: &str) -> bool {
        self.tags.iter().any(|t| t.clone() == tag.to_string()) // unnecessary clones
    }
}

