#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic() {
        let c = Config::new("db".into(), 42, vec!["prod".into(), "cloud".into()]);
        assert_eq!(c.get_name(), "db");
        assert!(c.has_tag("prod"));
        assert!(!c.has_tag("dev"));
    }

    #[test]
    fn test_summary() {
        let c = Config::new("api".into(), 8080, vec![]);
        let s = c.summary();
        assert!(s.contains("api"));
        assert!(s.contains("8080"));
    }

    #[test]
    fn test_get_tags() {
        let c = Config::new("x".into(), 1, vec!["a".into(), "b".into()]);
        assert_eq!(c.get_tags(), ["a", "b"]);
    }

    #[test]
    fn test_display() {
        let c = Config::new("svc".into(), 5, vec!["t1".into(), "t2".into()]);
        let s = format!("{}", c);
        assert!(s.contains("svc"));
        assert!(s.contains("5"));
        assert!(s.contains("t1"));
    }
}
